import math

def count_rectangles(m, allowed_steps):
    # Count lines by orientation index s = (i+j) mod m for each unordered pair {i,j}
    L = [0]*m
    for i in range(m):
        for j in range(i+1, m):
            delta = j - i
            d = delta if delta <= m - delta else m - delta  # symmetric step size in [1, m//2]
            if d in allowed_steps:
                s = (i + j) % m
                L[s] += 1
    rects = 0
    half = m//2
    # Sum over unique perpendicular pairs: s and s+half
    for s in range(half):
        A = L[s]
        B = L[(s + half) % m]
        if A >= 2 and B >= 2:
            rects += (A*(A-1)//2) * (B*(B-1)//2)
    return rects, L

